const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const fresh=()=>({day:1,phase:'day',view:'home',health:100,maxHealth:100,food:4,scrap:8,wood:5,cloth:5,parts:4,bandage:2,ammo38:0,ammo556:0,plot:0,bench:0,bagTier:0,bagCap:8,weapon:'Pipe',durability:{Pipe:12,Revolver:20,Carbine:24},has:{Pipe:true,Revolver:false,Carbine:false},expeditionDone:false,field:{},location:null,threat:0,zombies:0,zombie:{hp:0,max:0,name:'Shambler',damage:8},distance:0,round:1,screech:false,feed:[],encounter:false,gameOver:false});
let state;try{state={...fresh(),...JSON.parse(localStorage.getItem('afterlight-save')||'{}')};state.durability={...fresh().durability,...state.durability};state.has={...fresh().has,...state.has};state.field=state.field||{};}catch(e){state=fresh()}
const locations=[{id:'playground',name:'Playground',icon:'⌁',tier:1,threat:0,desc:'Small caches under the climbing frame. Few infected, mostly basics.',rolls:'1–3 loot rolls',unlock:1,pools:[['food',45],['cloth',30],['scrap',25]],zombies:[0,1],dist:[3,5]},{id:'park',name:'Park',icon:'♧',tier:2,threat:1,desc:'Overgrown paths hide supplies. More cover—and more movement in the brush.',rolls:'2–4 loot rolls',unlock:2,pools:[['food',35],['wood',30],['cloth',20],['parts',15]],zombies:[1,2],dist:[2,5]},{id:'gym',name:'Gym',icon:'▦',tier:3,threat:2,desc:'A stronghold of useful salvage. Tight rooms make contact likely.',rolls:'3–5 loot rolls',unlock:3,pools:[['scrap',35],['parts',30],['food',20],['cloth',15]],zombies:[1,2],dist:[1,4]},{id:'city',name:'City Square',icon:'▧',tier:4,threat:3,desc:'The richest cache is exposed in the open. Expect a crowd.',rolls:'4–6 loot rolls',unlock:4,pools:[['parts',35],['scrap',30],['food',20],['ammo38',15]],zombies:[2,3],dist:[0,4]}];
const items={food:['Rations','Meals for nightly upkeep'],scrap:['Scrap metal','Common fabrication stock'],wood:['Timber','Shelter and tool stock'],cloth:['Cloth','Medical and pack material'],parts:['Machine parts','Precision components'],bandage:['Bandages','Heal 25 health in combat'],ammo38:['.38 rounds','Revolver ammunition'],ammo556:['5.56 rounds','Carbine ammunition']};
function save(){localStorage.setItem('afterlight-save',JSON.stringify(state))}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2100)}
function showModal(title,body,actions=[['Continue',()=>closeModal(),'btn']]){$('#modalTitle').textContent=title;$('#modalBody').textContent=body;$('#modalActions').innerHTML='';for(const [label,fn,cls='btn secondary'] of actions){const b=document.createElement('button');b.className=cls;b.textContent=label;b.onclick=fn;$('#modalActions').append(b)}$('#modal').classList.add('open')}
function closeModal(){$('#modal').classList.remove('open')}
function go(view){if(view==='map'&&(state.phase!=='day'||state.expeditionDone)){if(state.phase!=='day')return toast('The door is barred until dawn.');return toast('Today’s expedition is complete. End the night to travel again.')}if(view==='combat'&&!state.encounter)return;state.view=view;$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));render();save()}
function render(){const phase=state.phase==='day'?'DAY PHASE':'NIGHT PHASE';$('#dayLabel').textContent=`DAY ${String(state.day).padStart(2,'0')}`;$('#phaseLabel').textContent=phase;$('#healthText').textContent=`${state.health} / ${state.maxHealth}`;$('#healthMeter span').style.width=`${Math.max(0,state.health)}%`;$('#healthMeter').classList.toggle('danger',state.health<35);$('#resourceList').innerHTML=['food','scrap','wood','cloth','parts','bandage','ammo38','ammo556'].map(k=>`<div class="resource"><span>${items[k][0]}</span><strong>${state[k]||0}</strong></div>`).join('');$('#foodStatus').textContent=state.food;$('#bagStatus').textContent=`${state.bagCap} slots`;$('#weaponStatus').textContent=state.weapon;
const night=state.phase==='night';$('#homePhase').textContent=night?'Night phase':'Day phase';$('#homeTitle').innerHTML=night?'Make it through<br>another night.':'One more day.<br>One more chance.';$('#homeSub').textContent=night?'The streets can wait until dawn. Secure supplies, make repairs, and choose what the shelter needs most.':'The streets still have supplies. The shelter still needs them. Choose a route, keep your head, and be back before dark.';$('#heroAction').textContent=night?'End the night →':'Open the door →';$('#heroAction').onclick=night?endNight:()=>go('map');$('#doorHeading').textContent=night?'The door is barred.':'The street is waiting.';$('#doorText').textContent=night?'No expeditions after dusk. Use the quiet hours to prepare for tomorrow.':'Click the front door to review routes. One expedition per day; what you carry home is yours to keep.';$('#doorAction').textContent=night?'Review shelter tasks':'Review map  ↗';$('#doorBtn').disabled=night;$('#doorAction').onclick=night?()=>go('storage'):()=>go('map');$('#foodStatus').textContent=state.food;$('#bagStatus').textContent=`${state.bagCap} slots`;
$('#mapStatus').textContent=state.expeditionDone?'ROUTE CLOSED':'ROUTE OPEN';$('#locationGrid').innerHTML=locations.map(l=>{const locked=state.day<l.unlock||state.expeditionDone||state.phase!=='day';return `<article class="loc-card ${locked?'locked':''}"><div class="loc-top"><span class="loc-icon">${l.icon}</span><span class="difficulty">TIER ${l.tier} / THREAT ${l.threat}</span></div><h3>${l.name}</h3><p>${l.desc}</p><div class="loc-foot"><span>${l.rolls}</span><button class="btn ${locked?'secondary':''}" ${locked?'disabled':''} data-expedition="${l.id}">${state.day<l.unlock?'LOCKED':state.expeditionDone?'DONE':'SCOUT →'}</button></div></article>`}).join('');$$('[data-expedition]').forEach(b=>b.onclick=()=>startExpedition(b.dataset.expedition));
if(state.encounter){goIfDifferent('combat');updateCombat()}renderStorage();renderUpgrades();$('#storagePhase').textContent=night?'NIGHT CRAFTING':'DAYTIME · INSPECT';$('#upgradePhase').textContent=night?'UPGRADES AVAILABLE':'NIGHT REQUIRED';}
function goIfDifferent(v){if(state.view!==v){state.view=v;$$('.view').forEach(x=>x.classList.toggle('active',x.id===`view-${v}`));$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v))}}
function startExpedition(id){const l=locations.find(x=>x.id===id);if(!l||state.phase!=='day'||state.expeditionDone)return;state.location=l;state.threat=l.threat;state.encounter=true;state.expeditionDone=true;state.field={};state.zombies=random(l.zombies[0],l.zombies[1]);state.round=1;state.screech=false;spawnZombie(true);state.feed=[`<em>DAY ${state.day} / ${l.name}</em> — ${state.zombies} infected signature${state.zombies>1?'s':''}.`];goIfDifferent('combat');render();save()}
function random(a,b){return Math.floor(Math.random()*(b-a+1))+a}
function spawnZombie(first=false){const l=state.location;const names=['Shambler','Drifter','Rattler','Runner'];state.zombie={name:names[random(0,Math.min(3,l.tier))],max:12+l.tier*5+random(0,4),hp:12+l.tier*5+random(0,4),damage:6+l.tier*2+random(0,3)};state.distance=random(l.dist[0],l.dist[1]);if(first)state.round=1}
function log(text){state.feed.unshift(text);state.feed=state.feed.slice(0,9);$('#combatFeed').innerHTML=state.feed.map(x=>`<div class="feed-line">${x}</div>`).join('')}
function updateCombat(){if(!state.encounter)return;const z=state.zombie;$('#combatLocation').textContent=`${state.location.name} // THREAT ${state.threat}`;$('#zombieName').textContent=z.name;$('#zombieStatus').textContent=state.distance<=1?'At striking distance · hostile':'Unsteady · closing';$('#distanceReadout').innerHTML=`${state.distance} m<small>CONTACT RANGE</small>`;$('#rangeDot').style.left=`${Math.max(12,Math.min(82,12+(state.distance/6)*70))}%`;$('#zombieHpText').textContent=`${Math.max(0,z.hp)} / ${z.max}`;$('#zombieHpMeter').style.width=`${Math.max(0,z.hp/z.max*100)}%`;$('#roundLabel').textContent=`ROUND ${String(state.round).padStart(2,'0')}`;$('#combatTurn').textContent='YOUR TURN';$('#combatFeed').innerHTML=state.feed.map(x=>`<div class="feed-line">${x}</div>`).join('');const revolver=state.weapon==='Revolver',carbine=state.weapon==='Carbine';const ammoKey=carbine?'ammo556':'ammo38';const gun=state.has[state.weapon]&&(revolver||carbine);$('#shootDesc').textContent=gun?`${state.weapon} · ${state[ammoKey]} ${carbine?'5.56':'.38'} · ${state.durability[state.weapon]} wear`:'No ranged weapon equipped';$('#shootBtn').disabled=!gun||state[ammoKey]<1||state.durability[state.weapon]<=0;$('#meleeDesc').textContent=`${state.weapon==='Pipe'?'Pipe':'Sidearm butt'} · ${state.durability.Pipe} wear`;$('#itemDesc').textContent=`Bandage · restore 25 (${state.bandage})`;$('#itemBtn').disabled=state.bandage<1||state.health>=state.maxHealth;$('#escapeDesc').textContent=`Success chance ${escapeChance()}%`;$('#combatTip').textContent=state.distance<=1?'Contact! The infected attacks after every action that leaves it alive. Escape odds improve when you create distance.':'Ranged attacks are strongest beyond 2 m. The infected advances 1 m each turn until it can strike.';$('#bagReadout').textContent=`FIELD BAG · ${bagCount()} / ${state.bagCap} capacity · secured on escape/return`}
function escapeChance(){return Math.max(15,Math.min(90,65+7*state.distance-8*state.threat-(state.health<50?10:0)-(state.screech?10:0)))}
function combatAction(type){if(!state.encounter)return;let z=state.zombie;if(type==='shoot'){const isCarbine=state.weapon==='Carbine';const ammo=isCarbine?'ammo556':'ammo38';if(!state.has[state.weapon]||!state[ammo]||state.durability[state.weapon]<=0)return;state[ammo]--;const chance=Math.max(20,Math.min(92,82-12*Math.max(0,state.distance-2)-(state.distance===0?15:0)));if(Math.random()*100<chance){let damage=isCarbine?18:12;z.hp-=damage;state.durability[state.weapon]--;log(`<em>HIT</em> — ${state.weapon} deals ${damage}. (${chance}% chance)`)}else log(`<em>MISS</em> — shot goes wide. (${chance}% chance)`)}else if(type==='melee'){if(state.distance>1){state.distance=Math.max(0,state.distance-2);log(`You brace and close to ${state.distance} m. Pipe can't reach yet.`)}else{const damage=state.weapon==='Pipe'?7:4;z.hp-=damage;state.durability.Pipe=Math.max(0,state.durability.Pipe-1);log(`<em>HIT</em> — melee deals ${damage}.` )}}else if(type==='item'){if(!state.bandage||state.health>=state.maxHealth)return;state.bandage--;let before=state.health;state.health=Math.min(state.maxHealth,state.health+25);log(`Bandage used. Vitals ${before} → ${state.health}.`)}else if(type==='escape'){const chance=escapeChance();if(Math.random()*100<chance){log(`<em>ESCAPE SUCCESS</em> — ${chance}% check. You break contact safely.`);finishExpedition(true);return}log(`<em>ESCAPE FAILED</em> — ${chance}% check. The infected gets a free strike.`);zombieCounter(true);state.round++;updateCombat();save();return}
if(z.hp<=0){log(`<em>THREAT DOWN</em> — ${z.name} neutralized.`);state.zombies--;if(state.zombies>0){spawnZombie();log(`Movement ahead. ${state.zombies} hostile signature${state.zombies===1?'':'s'} remain.`)}else{log('<em>AREA CLEAR</em> — searching the location.');state.encounter=false;rollLoot();setTimeout(()=>finishExpedition(true),350);updateCombat();save();return}}
if(state.encounter){zombieCounter(false);state.round++;}updateCombat();if(state.health<=0)defeat();save()}
function zombieCounter(free=false){if(!state.encounter)return;const z=state.zombie;if(state.distance>1){state.distance=Math.max(0,state.distance-1);log(`${z.name} advances. Distance: ${state.distance} m.`);if(state.round%3===0&&Math.random()<.45){state.screech=true;log(`${z.name} screeches. Escape odds −10 points.`)}}else{const dmg=z.damage;state.health=Math.max(0,state.health-dmg);log(`<em>COUNTER</em> — ${z.name} strikes for ${dmg}. Vitals ${state.health}.`);state.screech=false}}
function bagCount(){return Object.values(state.field).reduce((a,b)=>a+b,0)}
function rollLoot(){const l=state.location;const rolls=random(l.tier,l.tier+2);for(let n=0;n<rolls;n++){if(bagCount()>=state.bagCap)break;let r=Math.random()*100,sum=0,key=l.pools[l.pools.length-1][0];for(const [k,p] of l.pools){sum+=p;if(r<sum){key=k;break}}state.field[key]=(state.field[key]||0)+1}log(`Scavenged ${bagCount()} unit${bagCount()===1?'':'s'}; capacity ${state.bagCap}.`)}
function finishExpedition(safe){state.encounter=false;state.phase='night';state.view='home';for(const [k,v] of Object.entries(state.field))state[k]=(state[k]||0)+v;const recovered=Object.entries(state.field).map(([k,v])=>`${items[k]?.[0]||k} ×${v}`).join(', ')||'no supplies';state.field={};state.screech=false;render();save();showModal(safe?'Returned to shelter':'Expedition over',`${safe?'The front door is barred behind you.':'You were overwhelmed and dragged home.'} Automatically secured: ${recovered}. Night phase is open.`,[['Go to shelter',()=>{closeModal();go('home')},'btn']])}
function defeat(){state.health=1;const recovered={};for(const [k,v] of Object.entries(state.field)){const half=Math.floor(v/2);if(half)recovered[k]=half}state.field=recovered;state.encounter=false;log('You collapse. A neighbor hauls you back; half the bag is lost.');finishExpedition(false)}
function abandon(){if(!state.encounter)return;showModal('Abandon expedition?','You can retreat now, but this is not a combat escape. Half of each field-bag stack (rounded down) is lost. The night phase begins.',[['Stay out',closeModal,'btn secondary'],['Abandon',()=>{for(const k in state.field)state.field[k]=Math.floor(state.field[k]/2);finishExpedition(false)},'btn danger']])}
function renderStorage(){const keys=Object.keys(items);$('#storageItems').innerHTML=keys.map(k=>`<div class="item-row"><span>${items[k][0]}<small>${items[k][1]}</small></span><span class="item-count">× ${state[k]||0}</span></div>`).join('');const recipes=[{id:'ammo38',title:'Load .38 rounds',desc:'Craft 4 revolver rounds.',cost:'1 scrap + 1 parts',need:state.bench>=1,can:state.scrap>=1&&state.parts>=1,action:()=>{state.scrap--;state.parts--;state.ammo38+=4}},{id:'ammo556',title:'Load 5.56 rounds',desc:'Craft 3 carbine rounds.',cost:'2 scrap + 1 parts',need:state.bench>=2,can:state.scrap>=2&&state.parts>=1,action:()=>{state.scrap-=2;state.parts--;state.ammo556+=3}},{id:'bandage',title:'Make bandage',desc:'Craft 1 field dressing.',cost:'1 cloth + 1 food',need:true,can:state.cloth>=1&&state.food>=1,action:()=>{state.cloth--;state.food--;state.bandage++}},{id:'pipe',title:'Make pipe weapon',desc:'Craft a fresh pipe; durability 12.',cost:'2 scrap + 1 wood',need:true,can:state.scrap>=2&&state.wood>=1,action:()=>{state.scrap-=2;state.wood--;state.has.Pipe=true;state.durability.Pipe=12}},{id:'revolver',title:'Build revolver',desc:'Equip a ranged sidearm. Uses .38 rounds.',cost:'4 scrap + 2 parts',need:state.bench>=1,can:state.scrap>=4&&state.parts>=2,action:()=>{state.scrap-=4;state.parts-=2;state.has.Revolver=true;state.weapon='Revolver';state.durability.Revolver=20}},{id:'carbine',title:'Build carbine',desc:'Equip a long-range rifle. Uses 5.56 rounds.',cost:'6 scrap + 4 parts',need:state.bench>=2,can:state.scrap>=6&&state.parts>=4,action:()=>{state.scrap-=6;state.parts-=4;state.has.Carbine=true;state.weapon='Carbine';state.durability.Carbine=24}},{id:'repair',title:'Repair equipped weapon',desc:'Restore 10 durability to current weapon.',cost:'2 scrap + 1 parts',need:true,can:state.scrap>=2&&state.parts>=1&&state.durability[state.weapon]<(state.weapon==='Pipe'?12:state.weapon==='Revolver'?20:24),action:()=>{state.scrap-=2;state.parts--;state.durability[state.weapon]=Math.min(state.weapon==='Pipe'?12:state.weapon==='Revolver'?20:24,state.durability[state.weapon]+10)}}];$('#recipeGrid').innerHTML=recipes.map(r=>`<div class="recipe"><div class="recipe-head"><h4>${r.title}</h4>${!r.need?'<span class="tag">LOCKED</span>':''}</div><p>${r.desc}<br><span class="recipe-cost">Cost: ${r.cost}</span></p><button class="btn secondary" data-craft="${r.id}" ${!r.need||!r.can||state.phase!=='night'?'disabled':''}>${state.phase==='night'?'CRAFT':'NIGHT ONLY'}</button></div>`).join('');$$('[data-craft]').forEach(b=>b.onclick=()=>craft(b.dataset.craft));}
function craft(id){if(state.phase!=='night')return toast('Crafting is only available during the night.');let recipes=[...document.querySelectorAll('[data-craft]')];const b=recipes.find(x=>x.dataset.craft===id);if(!b||b.disabled)return toast('Missing materials or required bench.');const map={ammo38:()=>{state.scrap--;state.parts--;state.ammo38+=4},ammo556:()=>{state.scrap-=2;state.parts--;state.ammo556+=3},bandage:()=>{state.cloth--;state.food--;state.bandage++},pipe:()=>{state.scrap-=2;state.wood--;state.has.Pipe=true;state.durability.Pipe=12},revolver:()=>{state.scrap-=4;state.parts-=2;state.has.Revolver=true;state.weapon='Revolver';state.durability.Revolver=20},carbine:()=>{state.scrap-=6;state.parts-=4;state.has.Carbine=true;state.weapon='Carbine';state.durability.Carbine=24},repair:()=>{state.scrap-=2;state.parts--;state.durability[state.weapon]=Math.min(state.weapon==='Pipe'?12:state.weapon==='Revolver'?20:24,state.durability[state.weapon]+10)}};map[id]();toast('Fabrication complete.');render();save()}

function renderUpgrades(){const night=state.phase==='night';const data=[{key:'plot',icon:'♧',name:'Food plot',level:state.plot,max:3,desc:`Produces ${state.plot} ration${state.plot===1?'':'s'} each night. More food means more days to explore.`,costs:[{wood:3,scrap:2},{wood:5,parts:3},{wood:7,parts:5}],benefit:'+1 ration / night'},{key:'bench',icon:'⚒',name:'Weapon bench',level:state.bench,max:2,desc:state.bench===0?'Unlock firearm crafting and .38 ammunition.':state.bench===1?'Unlock carbine and 5.56 ammunition.':'Maximum bench tier reached.',costs:[{scrap:4,parts:2},{scrap:6,parts:4}],benefit:state.bench===0?'Unlock revolver + .38':'+1 workshop tier'},{key:'bagTier',icon:'▤',name:'Field pack',level:state.bagTier,max:2,desc:`Current capacity: ${state.bagCap} units. Carry more loot home in one trip.`,costs:[{cloth:3,scrap:2},{cloth:5,parts:4}],benefit:'+4 bag capacity'}];$('#upgradeGrid').innerHTML=data.map(d=>{const c=d.costs[d.level];const can=c&&Object.entries(c).every(([k,v])=>state[k]>=v);const cost=c?Object.entries(c).map(([k,v])=>`${v} ${k}`).join(' + '):'MAX TIER';return `<article class="upgrade-card"><div class="upgrade-icon">${d.icon}</div><div class="upgrade-level">Tier ${d.level} / ${d.max}</div><h3>${d.name}</h3><p>${d.desc}<br><span style="color:#c6d17b">${d.benefit}</span></p><button class="btn ${can?'':'secondary'}" data-upgrade="${d.key}" ${!night||!c||!can?'disabled':''}>${!c?'MAXED':!night?'NIGHT ONLY':`BUILD · ${cost}`}</button></article>`}).join('');$$('[data-upgrade]').forEach(b=>b.onclick=()=>upgrade(b.dataset.upgrade))}
function upgrade(key){if(state.phase!=='night')return toast('Upgrades can only be built at night.');let costs={plot:[{wood:3,scrap:2},{wood:5,parts:3},{wood:7,parts:5}],bench:[{scrap:4,parts:2},{scrap:6,parts:4}],bagTier:[{cloth:3,scrap:2},{cloth:5,parts:4}]};const max={plot:3,bench:2,bagTier:2}[key];const level=state[key];if(level>=max)return;const cost=costs[key][level];if(!Object.entries(cost).every(([k,v])=>state[k]>=v))return toast('Not enough materials.');for(const [k,v] of Object.entries(cost))state[k]-=v;state[key]++;if(key==='bagTier')state.bagCap+=4;toast(`${key==='bagTier'?'Field pack':key==='bench'?'Weapon bench':'Food plot'} upgraded.`);render();save()}
function endNight(){if(state.phase!=='night')return;let report=[];if(state.food>0){state.food--;report.push('1 ration consumed.')}else{state.health=Math.max(1,state.health-8);report.push('No food: lost 8 health.')}if(state.plot){state.food+=state.plot;report.push(`Food plot produced ${state.plot} ration${state.plot===1?'':'s'}.`)}state.health=Math.min(state.maxHealth,state.health+4);report.push('Rest recovered up to 4 health.');state.day++;state.phase='day';state.expeditionDone=false;state.view='home';render();save();showModal(`Day ${state.day} // dawn`,report.join(' ')+` The neighborhood is open again. New route access unlocks on day 2 (Park), day 3 (Gym), and day 4 (City Square).`,[['Start the day',()=>{closeModal();go('home')},'btn']])}
$('#doorBtn').onclick=()=>go('map');$('#doorAction').onclick=()=>go(state.phase==='day'?'map':'storage');$('#heroAction').onclick=()=>state.phase==='day'?go('map'):endNight();$('#helpBtn').onclick=()=>go('manual');$('#abandonBtn').onclick=abandon;$('#shootBtn').onclick=()=>combatAction('shoot');$('#meleeBtn').onclick=()=>combatAction('melee');$('#itemBtn').onclick=()=>combatAction('item');$('#escapeBtn').onclick=()=>combatAction('escape');$$('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});
function init(){if(!state.maxHealth)state.maxHealth=100;if(state.bagCap==null)state.bagCap=8;if(state.view==='combat'&&!state.encounter)state.view='home';render();if(state.gameOver){state.gameOver=false;state.health=50;state.phase='day';state.encounter=false;state.view='home';save();showModal('Shelter protocol restarted','Mara survived. You return with 50 health at the next dawn. Your chest and upgrades remain intact.',[['Continue',closeModal,'btn']])}}
init();
</script>
</body>
</html>

