 {id:'garden',name:'Rooftop garden',icon:'♧',max:3,desc:'Produce +1 ration each night per tier, after tonight’s ration is consumed.',base:{wood:3,scrap:1},step:{wood:2,scrap:2}},
 {id:'barricade',name:'Door barricade',icon:'▤',max:3,desc:'Reduce incoming infected damage by 2 per tier, minimum 1.',base:{wood:3,scrap:2},step:{wood:2,scrap:2}},
