const fresh=()=>({day:1,phase:'day',health:100,maxHealth:100,inv:{food:4,scrap:3,wood:2,parts:1,cloth:2,bandage:1,ammo38:0,ammo556:0},weapons:{pipe:12,revolver:0,carbine:0},weapon:'pipe',upgrades:{bench:0,garden:0,barricade:0,pack:0,bunk:0},expedition:null,routeDone:false,log:['Shelter protocol initialized. One route is available today.']});
function load(){try{const v=JSON.parse(localStorage.getItem(STORE));if(!v||typeof v!=='object')return fresh();const d=fresh();return {...d,...v,inv:{...d.inv,...v.inv},weapons:{...d.weapons,...v.weapons},upgrades:{...d.upgrades,...v.upgrades},log:Array.isArray(v.log)?v.log.slice(-12):d.log};}catch{return fresh();}}
let s=load(),toastTimer;
function save(){try{localStorage.setItem(STORE,JSON.stringify(s));}catch{}}
function toast(m){const el=$('toast');el.textContent=m;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200);}
function showView(name){document.querySelectorAll('.view').forEach(e=>e.classList.toggle('active',e.id==='view-'+name));document.querySelectorAll('[data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===name));window.scrollTo({top:0,behavior:'smooth'});}
function itemName(k){return ITEMS[k]?.[0]||k;}
function costText(cost){return Object.entries(cost).map(([k,n])=>`${n} ${itemName(k)}`).join(' · ');}
function canPay(cost){return Object.entries(cost).every(([k,n])=>(s.inv[k]||0)>=n);}
function pay(cost){Object.entries(cost).forEach(([k,n])=>s.inv[k]-=n);}
function bagCount(bag=s.expedition?.bag||{}){return Object.values(bag).reduce((a,b)=>a+b,0);}
function bagCap(){return 8+4*s.upgrades.pack;}
function stashBag(bag,ratio=1){Object.entries(bag||{}).forEach(([k,n])=>s.inv[k]=(s.inv[k]||0)+Math.floor(n*ratio));}
function addBag(k,n){const e=s.expedition;if(!e)return;const room=Math.max(0,bagCap()-bagCount());const got=Math.min(n,room);if(got)e.bag[k]=(e.bag[k]||0)+got;return got;}
function showModal(title,body,actions){$('modalTitle').textContent=title;$('modalBody').textContent=body;const box=$('modalActions');box.innerHTML='';actions.forEach(a=>{const b=document.createElement('button');b.className='btn '+(a.secondary?'secondary':'');b.textContent=a.label;b.dataset.action=a.action;box.append(b);});$('modal').classList.add('open');}
function closeModal(){$('modal').classList.remove('open');}
function renderResources(){const entries=['food','scrap','wood','parts','cloth','bandage','ammo38','ammo556'];$('resourceList').innerHTML=entries.map(k=>`<div class="resource-row"><span>${ITEMS[k][1]} ${itemName(k)}</span><strong>${s.inv[k]||0}</strong></div>`).join('');$('storageItems').innerHTML=entries.map(k=>`<div class="item-row"><span>${ITEMS[k][1]} ${itemName(k)}<small>${k.startsWith('ammo')?'Ammunition':k==='food'?'One ration is consumed each night':'Shelter supply'}</small></span><span class="item-count">× ${s.inv[k]||0}</span></div>`).join('')+Object.keys(WEAPONS).map(k=>`<div class="item-row"><span>${WEAPONS[k].name}<small>${s.weapon===k?'Equipped':'Weapon'} · durability ${s.weapons[k]||0}/${WEAPONS[k].max}</small></span><span class="item-count">${s.weapons[k]>0?`<button class="btn secondary" data-equip="${k}">${s.weapon===k?'Ready':'Equip'}</button>`:'—'}</span></div>`).join('');}
function renderRoutes(){const grid=$('locationGrid');grid.innerHTML=ROUTES.map(r=>{const locked=s.day<r.day,done=s.routeDone||s.phase!=='day';return `<article class="loc-card ${locked?'locked':''}"><div class="loc-top"><span class="loc-icon">${r.icon}</span><span class="difficulty">${'◆'.repeat(r.tier+1)} / THREAT ${r.tier+1}</span></div><h3>${r.name}</h3><p>${locked?`Unlocks on day ${String(r.day).padStart(2,'0')}.`:r.desc}</p><div class="loc-foot"><span>${r.distance} m · ${r.tier===0?'light':r.tier<3?'moderate':'severe'} threat</span><button class="btn ${locked||done?'secondary':''}" data-route="${r.id}" ${locked||done?'disabled':''}>${locked?'Locked':done?'Route closed':'Enter route →'}</button></div></article>`;}).join('');}
function renderRecipes(){const canNight=s.phase==='night';$('recipeGrid').innerHTML=RECIPES.map(r=>{const locked=(r.bench||0)>s.upgrades.bench,owns=r.weapon&&s.weapons[r.weapon]>0&&r.weapon!=='pipe';let allowed=canNight&&!locked&&canPay(r.cost)&&!owns;if(r.repair)allowed=canNight&&canPay(r.cost)&&(s.weapons[s.weapon]||0)<WEAPONS[s.weapon].max;return `<article class="recipe"><div class="recipe-head"><h4>${r.name}</h4><span class="recipe-cost">${locked?`Workbench ${r.bench} required`:costText(r.cost)}</span></div><p>${r.desc}${owns?' Already fabricated.':''}</p><button class="btn ${allowed?'':'secondary'}" data-craft="${r.id}" ${allowed?'':'disabled'}>${r.repair?'Repair':owns?'Owned':locked?'Locked':!canNight?'Night only':'Fabricate'}</button></article>`;}).join('');}
function upgradeCost(u){return Object.fromEntries(Object.keys(u.base).map(k=>[k,u.base[k]+(u.step[k]||0)*s.upgrades[u.id]]));}
function renderUpgrades(){ $('upgradeGrid').innerHTML=UPGRADES.map(u=>{const lv=s.upgrades[u.id],cost=upgradeCost(u),max=lv>=u.max,ok=s.phase==='night'&&!max&&canPay(cost);return `<article class="upgrade-card"><div class="upgrade-icon">${u.icon}</div><div class="upgrade-level">${max?'MAX LEVEL':`TIER ${lv} / ${u.max}`}</div><h3>${u.name}</h3><p>${u.desc}</p><span class="recipe-cost">${max?'Fully upgraded':costText(cost)}</span><button class="btn ${ok?'':'secondary'}" data-upgrade="${u.id}" ${ok?'':'disabled'}>${max?'Complete':s.phase==='night'?'Install tier '+(lv+1):'Night required'}</button></article>`;}).join('');}
function updateCombat(){const e=s.expedition;if(!e)return;const z=e.zombie;const weapon=WEAPONS[s.weapon];$('combatLocation').textContent=`Expedition // ${e.routeName}`;$('zombieName').textContent=z.name;$('zombieStatus').textContent=z.hp<z.maxHp?'Wounded · closing':'Unsteady · closing';$('distanceReadout').innerHTML=`${e.distance} m<small>${e.distance===0?'CONTACT':e.distance<=1?'MELEE RANGE':'CONTACT RANGE'}</small>`;$('zombieHpText').textContent=`${z.hp} / ${z.maxHp}`;$('zombieHpMeter').style.width=`${Math.max(0,z.hp/z.maxHp*100)}%`;$('rangeDot').style.left=`${Math.max(5,Math.min(95,90-e.distance*14))}%`;$('roundLabel').textContent=`ROUND ${String(e.round).padStart(2,'0')}`;$('combatTurn').textContent='YOUR TURN';$('combatFeed').innerHTML=e.feed.slice(-5).map(x=>`<div>${x}</div>`).join('');const hasRanged=weapon.ammo&&s.weapons[s.weapon]>0&&s.inv[weapon.ammo]>0;$('shootBtn').disabled=!hasRanged;$('shootDesc').textContent=hasRanged?`${weapon.name} · ${s.inv[weapon.ammo]} rounds · ${weapon.damage} dmg`:'No loaded ranged weapon';$('meleeBtn').disabled=!s.weapons.pipe||e.distance>1;$('meleeDesc').textContent=e.distance>1?'Too far · close to 1 m':`Pipe · ${WEAPONS.pipe.damage} damage`;$('itemBtn').disabled=!(s.inv.bandage>0&&s.health<s.maxHealth);$('itemDesc').textContent=s.inv.bandage?`Bandage · restore 25 (${s.inv.bandage})`:'No bandages';const chance=escapeChance();$('escapeDesc').textContent=`Success chance ${chance}%`;$('combatTip').textContent=e.rattled?'The infected rattled you. Escape chance is reduced by 10 points this turn.':'At distance 0–1 m, the infected can strike after your action.';$('bagReadout').textContent=`FIELD BAG · ${bagCount()} / ${bagCap()} capacity`;$('abandonBtn').disabled=false;}
function escapeChance(){const e=s.expedition;if(!e)return 0;return Math.max(15,Math.min(90,Math.round(65+7*e.distance-8*e.threat-(s.health<s.maxHealth/2?10:0)-(e.rattled?10:0))));}
function render(){const night=s.phase==='night';$('dayLabel').textContent=`DAY ${String(s.day).padStart(2,'0')}`;$('phaseLabel').textContent=night?'NIGHT PHASE':s.phase==='combat'?'EXPEDITION':'DAY PHASE';$('healthText').textContent=`${s.health} / ${s.maxHealth}`;$('healthMeter').querySelector('span').style.width=`${Math.max(0,s.health/s.maxHealth*100)}%`;$('foodStatus').textContent=s.inv.food||0;$('bagStatus').textContent=s.expedition?`${bagCount()} / ${bagCap()}`:`0 / ${bagCap()}`;$('weaponStatus').textContent=WEAPONS[s.weapon].name;$('homePhase').textContent=night?'Night phase':s.phase==='combat'?'Expedition active':'Day phase';$('homeTitle').innerHTML=night?'The door is barred.<br>Make it count.':'One more day.<br>One more chance.';$('homeSub').textContent=night?'The streets are quiet for now. Fabricate supplies, improve the shelter, then prepare for dawn.':'The streets still have supplies. The shelter still needs them. Choose a route, keep your head, and be back before dark.';$('doorHeading').textContent=night?'Night watch.':s.phase==='combat'?'You are beyond the door.':'The street is waiting.';$('doorText').textContent=night?'Use the workbench and shelter systems before ending the night. One ration is consumed at dawn.':s.phase==='combat'?'An encounter is underway. Every choice costs exactly one response from the infected.':'One expedition per day; what you carry home is yours to keep.';$('heroAction').textContent=night?'Prepare for dawn →':s.phase==='combat'?'Return to encounter →':'Open the door →';$('heroAction').dataset.action=night?'dawn':s.phase==='combat'?'combat':'map';$('doorAction').textContent=night?'Review upgrades ↗':s.phase==='combat'?'Continue encounter ↗':'Review map ↗';$('doorAction').dataset.action=night?'upgrades':s.phase==='combat'?'combat':'map';$('mapStatus').textContent=s.phase==='day'&&!s.routeDone?'ROUTE OPEN':s.phase==='combat'?'EXPEDITION ACTIVE':'ROUTE CLOSED';$('storagePhase').textContent=night?'NIGHT FABRICATION':'NIGHT REQUIRED';$('upgradePhase').textContent=night?'NIGHT ACTIVE':'NIGHT REQUIRED';renderResources();renderRoutes();renderRecipes();renderUpgrades();if(s.phase==='combat'&&s.expedition){showView('combat');updateCombat();}else if($('view-combat').classList.contains('active'))showView('home');$('heroAction').disabled=s.phase==='combat';$('doorBtn').disabled=s.phase==='combat';}
function addLog(line){s.log.push(line);s.log=s.log.slice(-12);}
function startRoute(id){const r=ROUTES.find(x=>x.id===id);if(!r||s.phase!=='day'||s.routeDone||s.day<r.day)return;const names=['Shambler','Drifter','Raker','Hollow'];const hp=16+r.tier*7+Math.floor(Math.random()*7);const bag={};const e={routeId:r.id,routeName:r.name,threat:r.tier,distance:r.distance,round:1,rattled:false,bag,zombie:{name:names[Math.min(3,r.tier+Math.floor(Math.random()*2))],hp,maxHp:hp,damage:6+r.tier*2},feed:[r.drop]};s.expedition=e;for(let i=0;i<2+r.tier;i++){const item=r.pool[Math.floor(Math.random()*r.pool.length)];addBag(item,1);}s.phase='combat';e.feed.push(`You scavenge ${bagCount()} item${bagCount()===1?'':'s'} before contact.`);addLog(`Expedition started: ${r.name}.`);save();render();}
function response(){const e=s.expedition;if(!e)return;const z=e.zombie;e.round++;if(e.round%3===0&&!e.rattled&&Math.random()<.45){e.rattled=true;e.feed.push('The infected emits a piercing screech. Your next escape is harder.');return;}if(e.distance>1){e.distance=Math.max(0,e.distance-1);e.feed.push(`The ${z.name.toLowerCase()} closes to ${e.distance} m.`);return;}const raw=z.damage;const damage=Math.max(1,raw-2*s.upgrades.barricade);s.health=Math.max(0,s.health-damage);e.feed.push(`The infected strikes for ${damage} damage${damage<raw?' (barricade absorbed '+(raw-damage)+')':''}.`);if(s.health<=0){finishRun('defeat');}}
function act(type){const e=s.expedition;if(!e||s.phase!=='combat')return;let acted=false,kill=false;
 if(type==='shoot'){const w=WEAPONS[s.weapon];if(!w.ammo||s.weapons[s.weapon]<=0||s.inv[w.ammo]<=0)return;const contact=e.distance===0;const hitChance=Math.max(20,Math.min(92,82-12*Math.max(0,e.distance-2)-(contact?15:0)));s.inv[w.ammo]--;acted=true;if(Math.random()*100<hitChance){e.zombie.hp-=w.damage;s.weapons[s.weapon]--;e.feed.push(`Shot hits (${hitChance}%): ${w.damage} damage.`);}else e.feed.push(`Shot misses (${hitChance}%).`);}
 else if(type==='melee'){if(e.distance>1||s.weapons.pipe<=0)return;acted=true;if(Math.random()<.9){e.zombie.hp-=WEAPONS.pipe.damage;s.weapons.pipe--;e.feed.push(`Pipe connects for ${WEAPONS.pipe.damage} damage.`);}else e.feed.push('The pipe swing misses.');}
 else if(type==='item'){if(!s.inv.bandage||s.health>=s.maxHealth)return;s.inv.bandage--;s.health=Math.min(s.maxHealth,s.health+25);e.feed.push('You bind the wound and restore 25 health.');acted=true;}
 else if(type==='escape'){const chance=escapeChance();e.rattled=false;if(Math.random()*100<chance){e.feed.push(`Escape succeeds (${chance}%). You break contact with the bag intact.`);finishRun('escape');return;}e.feed.push(`Escape fails (${chance}%). The infected is still on you.`);acted=true;}
 if(!acted)return;if(e.zombie.hp<=0){e.feed.push(`The ${e.zombie.name.toLowerCase()} collapses. Route clear.`);kill=true;const item=e.routeId==='square'?'ammo38':e.routeId==='gym'?'parts':'scrap';addBag(item,1+Math.floor(Math.random()*2));finishRun('victory');return;}response();if(s.phase==='combat'){if(kill)return;save();render();}}
function finishRun(outcome){const e=s.expedition;if(!e)return;let recovered=e.bag;if(outcome==='defeat'){const half={};Object.entries(e.bag).forEach(([k,n])=>half[k]=Math.floor(n/2));recovered=half;}stashBag(recovered);const count=Object.values(recovered).reduce((a,b)=>a+b,0);const route=e.routeName;s.routeDone=true;s.expedition=null;s.phase='night';if(outcome==='defeat'){s.health=Math.max(1,Math.floor(s.maxHealth*.25));addLog(`Defeated on ${route}; ${count} item(s) recovered.`);showModal('Overrun',`You were brought down on the ${route} route. ${count} item(s) made it back to the chest. The shelter doors held.`,[{label:'Manage shelter',action:'close-night'}]);}else{addLog(`${outcome==='escape'?'Escaped':'Cleared'} ${route}; ${count} item(s) transferred to chest.`);showModal(outcome==='escape'?'Extraction complete':'Route secured',`${count} item(s) transferred automatically to the home chest. The expedition is over for today.`,[{label:'Continue to night',action:'close-night'}]);}save();render();}
function craft(id){if(s.phase!=='night')return;const r=RECIPES.find(x=>x.id===id);if(!r||(r.bench||0)>s.upgrades.bench||!canPay(r.cost))return;if(r.weapon&&s.weapons[r.weapon]>0){toast('That weapon is already fabricated.');return;}if(r.repair&&(s.weapons[s.weapon]||0)>=WEAPONS[s.weapon].max){toast('Equipped weapon is already serviceable.');return;}pay(r.cost);if(r.weapon){s.weapons[r.weapon]=WEAPONS[r.weapon].max;s.weapon=r.weapon;toast(`${r.name} fabricated and equipped.`);}else if(r.repair){s.weapons[s.weapon]=Math.min(WEAPONS[s.weapon].max,s.weapons[s.weapon]+10);toast(`${WEAPONS[s.weapon].name} repaired.`);}else{Object.entries(r.out).forEach(([k,n])=>s.inv[k]=(s.inv[k]||0)+n);toast(`${r.name} fabricated.`);}save();render();}
function upgrade(id){if(s.phase!=='night')return;const u=UPGRADES.find(x=>x.id===id);if(!u||s.upgrades[id]>=u.max)return;const cost=upgradeCost(u);if(!canPay(cost))return;pay(cost);s.upgrades[id]++;if(id==='bunk'){s.maxHealth+=10;s.health=Math.min(s.maxHealth,s.health+10);}addLog(`${u.name} upgraded to tier ${s.upgrades[id]}.`);toast(`${u.name} improved.`);save();render();}
function dawn(){if(s.phase!=='night')return;let msg='';if(s.inv.food>0){s.inv.food--;msg='One ration consumed.';}else{s.health=Math.max(1,s.health-12);msg='No food: health fell by 12.';}const produce=s.upgrades.garden;if(produce)s.inv.food+=produce;const heal=s.upgrades.bunk?8:0;s.health=Math.min(s.maxHealth,s.health+heal);s.day++;s.phase='day';s.routeDone=false;s.expedition=null;addLog(`Day ${s.day} begins. ${msg}${produce?` Garden produced ${produce} ration(s).`:''}`);save();render();showModal(`Day ${String(s.day).padStart(2,'0')}`,`${msg}${produce?` Garden production: +${produce} ration(s). `:''}${heal?`Bunk restored ${heal} health. `:''}A new expedition route is available.`,[{label:'Begin day',action:'dismiss'}]);}
function action(action){if(action==='map')showView('map');else if(action==='home')showView('home');else if(action==='storage')showView('storage');else if(action==='upgrades')showView('upgrades');else if(action==='manual')showView('manual');else if(action==='combat'){if(s.phase==='combat'){showView('combat');updateCombat();}}else if(action==='dawn')showModal('End the night?','Consume one ration, apply garden production and bunk recovery, then begin the next day.',[{label:'Stay here',action:'dismiss',secondary:true},{label:'End night',action:'confirm-dawn'}]);else if(action==='confirm-dawn'){closeModal();dawn();}else if(action==='close-night'){closeModal();showView('home');}else if(action==='dismiss'){closeModal();}}
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.view){showView(b.dataset.view);return;}if(b.dataset.route){startRoute(b.dataset.route);return;}if(b.dataset.craft){craft(b.dataset.craft);return;}if(b.dataset.upgrade){upgrade(b.dataset.upgrade);return;}if(b.dataset.equip){const k=b.dataset.equip;if((s.weapons[k]||0)>0){s.weapon=k;save();render();toast(`${WEAPONS[k].name} equipped.`);}return;}if(b.dataset.action){action(b.dataset.action);return;}switch(b.id){case'helpBtn':showView('manual');break;case'heroAction':case'doorAction':action(b.dataset.action);break;case'doorBtn':showView(s.phase==='night'?'upgrades':'map');break;case'shootBtn':act('shoot');break;case'meleeBtn':act('melee');break;case'itemBtn':act('item');break;case'escapeBtn':act('escape');break;case'abandonBtn':if(s.phase==='combat')showModal('Abandon expedition?','You will lose half of the field bag, rounded down, and return to the shelter night phase.',[{label:'Keep scavenging',action:'dismiss',secondary:true},{label:'Abandon run',action:'confirm-abandon'}]);break;case'confirm-abandon':closeModal();finishRun('defeat');break;}});
$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal();});
function init(){render();if(!localStorage.getItem(STORE))save();}
init();

